"""Attribute observers for tracking statistics at tree nodes."""

from typing import List, Tuple, Optional
import math


class AttributeObserver:
    """Base class for attribute class observers."""

    def observe(self, attr_value: float, class_label: int, weight: float = 1.0):
        raise NotImplementedError

    def get_best_split_suggestion(self, num_classes: int) -> Tuple[float, float, List[List[float]]]:
        """Return (info_gain, split_value, post_split_dists)."""
        raise NotImplementedError


class NominalAttributeObserver(AttributeObserver):
    """Tracks statistics for nominal (discrete) attributes."""

    def __init__(self):
        self.counts: dict = {}  # {attr_value: {class: count}}

    def observe(self, attr_value: float, class_label: int, weight: float = 1.0):
        val = int(attr_value)
        if val not in self.counts:
            self.counts[val] = {}
        if class_label not in self.counts[val]:
            self.counts[val][class_label] = 0.0
        self.counts[val][class_label] += weight

    def get_best_split_suggestion(self, num_classes: int) -> Tuple[float, float, List[List[float]]]:
        from classifiers import compute_info_gain
        pre_counts = [0.0] * num_classes
        post_counts = []
        for val_counts in self.counts.values():
            branch = [0.0] * num_classes
            for cls, cnt in val_counts.items():
                if cls < num_classes:
                    branch[cls] += cnt
                    pre_counts[cls] += cnt
            post_counts.append(branch)
        if not post_counts:
            return (0.0, 0.0, [])
        gain = compute_info_gain(pre_counts, post_counts)
        return (gain, 0.0, post_counts)


class NumericAttributeObserver(AttributeObserver):
    """Binary split observer for numeric attributes using sorted bins."""

    def __init__(self, num_bins: int = 10):
        self.num_bins = num_bins
        self.min_val = float('inf')
        self.max_val = float('-inf')
        self.bin_counts: List[dict] = [{} for _ in range(num_bins)]
        self.total_per_class: dict = {}
        self.total_count = 0

    def observe(self, attr_value: float, class_label: int, weight: float = 1.0):
        if attr_value < self.min_val:
            self.min_val = attr_value
        if attr_value > self.max_val:
            self.max_val = attr_value
        if class_label not in self.total_per_class:
            self.total_per_class[class_label] = 0.0
        self.total_per_class[class_label] += weight
        self.total_count += weight
        bin_idx = self._get_bin(attr_value)
        if class_label not in self.bin_counts[bin_idx]:
            self.bin_counts[bin_idx][class_label] = 0.0
        self.bin_counts[bin_idx][class_label] += weight

    def _get_bin(self, value: float) -> int:
        if self.max_val <= self.min_val:
            return 0
        norm = (value - self.min_val) / (self.max_val - self.min_val)
        bin_idx = int(norm * (self.num_bins - 1))
        return max(0, min(self.num_bins - 1, bin_idx))

    def get_best_split_suggestion(self, num_classes: int) -> Tuple[float, float, List[List[float]]]:
        from classifiers import compute_info_gain
        if self.total_count == 0 or self.max_val <= self.min_val:
            return (0.0, 0.0, [])

        pre_counts = [0.0] * num_classes
        for cls, cnt in self.total_per_class.items():
            if cls < num_classes:
                pre_counts[cls] = cnt

        best_gain = 0.0
        best_split = 0.0
        best_post = []

        left_counts = [0.0] * num_classes
        for i in range(self.num_bins - 1):
            for cls, cnt in self.bin_counts[i].items():
                if cls < num_classes:
                    left_counts[cls] += cnt
            right_counts = [pre_counts[c] - left_counts[c] for c in range(num_classes)]
            if sum(left_counts) > 0 and sum(right_counts) > 0:
                gain = compute_info_gain(pre_counts, [left_counts[:], right_counts])
                if gain > best_gain:
                    best_gain = gain
                    split_point = self.min_val + (i + 1) * (self.max_val - self.min_val) / self.num_bins
                    best_split = split_point
                    best_post = [left_counts[:], right_counts[:]]

        return (best_gain, best_split, best_post)
